import {useEffect,useState,useRef} from 'react';
import {createRoot} from 'react-dom/client';
import {UaiAdmin} from '@uai/admin-module';
import '@uai/admin-module/styles.css';
async function request(path:string,body?:unknown){const response=await fetch(path,body===undefined?{cache:'no-store'}:{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(data.error??'Request failed');return data;}
function Parent(){
 const stream=useRef<EventSource|null>(null);const [streamState,setStreamState]=useState('closed');
 const [user,setUser]=useState('alice'),[session,setSession]=useState<{user:string;teams:string[];role:string|null;product_roles:Record<string,string>}|null>(null),[team,setTeam]=useState(sessionStorage.getItem('fixture-team')??'alpha'),[balance,setBalance]=useState<any>(null),[error,setError]=useState(''),[actionResult,setActionResult]=useState('');
 useEffect(()=>()=>stream.current?.close(),[]);
 function connect(){stream.current?.close();setStreamState('connecting');const events=new EventSource(`/fixture/events?team=${encodeURIComponent(team)}`);stream.current=events;events.onmessage=()=>setStreamState('connected');events.onerror=()=>{setStreamState('closed');events.close()};}
 async function refresh(){try{setSession(await request('/fixture/session'));setError('')}catch(e){setSession(null);setBalance(null);setError((e as Error).message)}}
 async function checkAction(action:string){try{const result=await request('/fixture/product-action',{team,action});setActionResult(`${action}: allowed for ${result.account_id}. Synthetic check only, no model request.`);setError('')}catch(e){setActionResult('');setError((e as Error).message)}}
 async function load(){try{setBalance(await request(`/fixture/balance?team=${encodeURIComponent(team)}`));setError('')}catch(e){setBalance(null);setError((e as Error).message)}}
 useEffect(()=>{void refresh()},[]);useEffect(()=>{sessionStorage.setItem('fixture-team',team);setBalance(null)},[team]);
 async function control(action:string){await request('/fixture/control',{action});await refresh();setBalance(null)}
 return <main style={{maxWidth:780,margin:'40px auto',padding:24,fontFamily:'system-ui'}}><h1 style={{fontSize:28}}>External identity test host</h1><p>Synthetic sessions and balances. Loopback only. No real providers.</p><section style={{marginTop:24}}><label>Fixture user <select aria-label="Fixture user" value={user} onChange={e=>setUser(e.target.value)}>{['alice','bob','team-admin','viewer','admin'].map(id=><option key={id}>{id}</option>)}</select></label> <button onClick={async()=>{await request('/fixture/login',{user});await refresh();setBalance(null)}}>Sign in</button></section>{session&&<><p>Signed in as <strong>{session.user}</strong>. Staff role: <strong>{session.role??'none'}</strong>.</p><p>Current memberships: {session.teams.join(', ')||'none'}</p><a href="/admin">Open administration</a><section style={{marginTop:24}}><h2>Team wallet</h2><p>Team selection is stored per tab. The backend verifies current membership on every balance request.</p><label>Selected team <select aria-label="Selected team" value={team} onChange={e=>setTeam(e.target.value)}><option>alpha</option><option>beta</option></select></label> <button onClick={()=>void load()}>Read balance</button> <button onClick={connect}>Connect team events</button><p role="status">Team event stream: {streamState}</p>{balance&&<div><p>Team {balance.team}: {balance.wallet.available_units} units</p><pre style={{whiteSpace:'pre-wrap'}}>{JSON.stringify(balance,null,2)}</pre></div>}</section><section style={{marginTop:24}}><h2>Product permissions</h2><p>Selected team role: {session.product_roles[team]??'none'}. View, chat and generation permissions are cumulative. These checks do not submit model requests.</p><button onClick={()=>void checkAction('chat')}>Check chat access</button> <button onClick={()=>void checkAction('generate')}>Check generation access</button>{actionResult&&<p role="status">{actionResult}</p>}<h2>Test controls</h2><div style={{display:'flex',gap:12,flexWrap:'wrap'}}><button onClick={()=>void control('revoke-session')}>Revoke current session</button><button onClick={()=>void control('remove-alice-alpha')}>Remove Alice from Alpha</button><button onClick={()=>void control('downgrade-admin')}>Downgrade admin to viewer</button><button onClick={()=>void control('reset')}>Reset memberships and roles</button><button onClick={()=>void refresh()}>Refresh session</button></div></section></>}{error&&<p role="alert" style={{color:'#b91c1c',marginTop:16}}>{error}</p>}</main>;
}
createRoot(document.getElementById('root')!).render(location.pathname.startsWith('/admin')?<UaiAdmin/>:<Parent/>);
